import { test, expect } from '@playwright/test';

test.describe('Video Captions Accessibility', () => {
  let videoUrl: string;

  test.beforeEach(async ({ page }) => {
    // Navigate to a page with video content
    await page.goto('https://example.com/videos');
    videoUrl = page.url();
  });

  test('should display captions toggle button on video player', async ({ page }) => {
    // Locate the video player
    const videoPlayer = page.getByRole('region', { name: /video player/i });

    // Verify video player exists
    await expect(videoPlayer).toBeVisible();

    // Look for captions toggle button
    const captionsButton = page.getByRole('button', { name: /captions|cc|subtitles/i });

    // Verify captions button is present and visible
    await expect(captionsButton).toBeVisible();
    await expect(captionsButton).toBeEnabled();
  });

  test('should enable captions when captions button is clicked', async ({ page }) => {
    // Locate and click the captions toggle button
    const captionsButton = page.getByRole('button', { name: /captions|cc|subtitles/i });

    // Click to enable captions
    await captionsButton.click();

    // Verify captions are now visible
    const captionsTrack = page.locator('[kind="captions"]');
    await expect(captionsTrack).toBeVisible();

    // Verify button state indicates captions are on
    await expect(captionsButton).toHaveAttribute('aria-pressed', 'true');
  });

  test('should display caption text synchronized with video content', async ({ page }) => {
    // Enable captions first
    const captionsButton = page.getByRole('button', { name: /captions|cc|subtitles/i });
    await captionsButton.click();

    // Wait for captions to be visible
    const captionText = page.getByRole('region', { name: /captions|subtitle/i });
    await expect(captionText).toBeVisible();

    // Verify caption content is not empty
    const captionContent = await captionText.textContent();
    expect(captionContent).toBeTruthy();
    expect(captionContent?.length).toBeGreaterThan(0);
  });

  test('should toggle captions on and off', async ({ page }) => {
    const captionsButton = page.getByRole('button', { name: /captions|cc|subtitles/i });
    const captionText = page.getByRole('region', { name: /captions|subtitle/i });

    // Initially captions should be off
    await expect(captionsButton).toHaveAttribute('aria-pressed', 'false');

    // Enable captions
    await captionsButton.click();
    await expect(captionsButton).toHaveAttribute('aria-pressed', 'true');
    await expect(captionText).toBeVisible();

    // Disable captions
    await captionsButton.click();
    await expect(captionsButton).toHaveAttribute('aria-pressed', 'false');
    await expect(captionText).not.toBeVisible();
  });

  test('should provide caption language selection if available', async ({ page }) => {
    // Look for caption settings or language selection
    const settingsButton = page.getByRole('button', { name: /settings|options|gear/i });

    if (await settingsButton.isVisible()) {
      await settingsButton.click();

      // Look for caption language options
      const captionLanguageOption = page.getByRole('menuitem', { name: /captions|subtitles|language/i });

      if (await captionLanguageOption.isVisible()) {
        await expect(captionLanguageOption).toBeEnabled();
      }
    }
  });

  test('should have keyboard accessible captions control', async ({ page }) => {
    // Focus on the captions button using keyboard
    const captionsButton = page.getByRole('button', { name: /captions|cc|subtitles/i });

    // Tab to the button
    await page.keyboard.press('Tab');

    // Verify button is focusable
    await expect(captionsButton).toBeFocused();

    // Activate captions using keyboard (Space or Enter)
    await page.keyboard.press('Space');

    // Verify captions are enabled
    await expect(captionsButton).toHaveAttribute('aria-pressed', 'true');
  });

  test('should persist caption preference across video playback', async ({ page }) => {
    const captionsButton = page.getByRole('button', { name: /captions|cc|subtitles/i });

    // Enable captions
    await captionsButton.click();
    await expect(captionsButton).toHaveAttribute('aria-pressed', 'true');

    // Play video (if play button exists)
    const playButton = page.getByRole('button', { name: /play/i });
    if (await playButton.isVisible()) {
      await playButton.click();

      // Wait a moment for video to play
      await page.waitForTimeout(2000);

      // Verify captions are still enabled
      await expect(captionsButton).toHaveAttribute('aria-pressed', 'true');
    }
  });
});
